#!/bin/sh
# uso: ./fazer.sh cena.html saida.mp4 [quadros]
cd "$(dirname "$0")"; H=$1; O=$2; N=${3:-1440}; rm -rf fr && mkdir fr
NODE_PATH=$(npm root -g) node -e "const {chromium}=require('playwright'),fs=require('fs');(async()=>{const b=await chromium.launch();await Promise.all([0,1,2,3].map(async k=>{const p=await b.newPage({viewport:{width:1280,height:720}});await p.goto('file://'+process.cwd()+'/$H');const mine=[];for(let i=k;i<$N;i+=4)mine.push(i);const out=await p.evaluate(async mine=>{const c=document.createElement('canvas');c.width=1280;c.height=720;const g=c.getContext('2d');const r=[];for(const i of mine){R(i);const u=URL.createObjectURL(new Blob([document.getElementById('s').outerHTML],{type:'image/svg+xml'}));const im=new Image();im.src=u;await im.decode();g.drawImage(im,0,0);r.push(c.toDataURL('image/jpeg',.88));URL.revokeObjectURL(u)}return r},mine);out.forEach((d,j)=>fs.writeFileSync('fr/'+String(mine[j]).padStart(4,'0')+'.jpg',Buffer.from(d.split(',')[1],'base64')))}));await b.close()})()"
F=$(python3 -c "import imageio_ffmpeg as i;print(i.get_ffmpeg_exe())"); $F -v error -y -framerate 12 -i fr/%04d.jpg -vf fps=24 -c:v libx264 -preset superfast -crf 23 -pix_fmt yuv420p "$O"; rm -rf fr
